export type IconProps = Omit<SVGProps<SVGSVGElement>, "ref"> & {
  size?: string | number;
  /** Keep the stroke the same thickness on screen whatever the icon's size. */
  absoluteStrokeWidth?: boolean;
};
/** The shape of every icon component here. Named for the call sites that predate the switch. */
export type LucideIcon = ForwardRefExoticComponent<IconProps & RefAttributes<SVGSVGElement>>;

function make(icon: IconSvgElement, name: string): LucideIcon {
  const Icon = forwardRef<SVGSVGElement, IconProps>(({ strokeWidth, ...props }, ref) => (
    <HugeiconsIcon
      ref={ref}
      icon={icon}
      aria-hidden="true"
      // Left unset, each glyph keeps the 1.5 the set was drawn at.
      strokeWidth={strokeWidth === undefined ? undefined : Number(strokeWidth)}
      {...props}
    />
  ));
  Icon.displayName = name;
  return Icon;
}

